const items = $input.all();
const secEmail = 'security@company.com';

const colorMap = { CRITICAL: '#ff0000', HIGH: '#ff8800', MEDIUM: '#ffdd00', LOW: '#0088ff' };
const slaMap   = { CRITICAL: '24 hours', HIGH: '72 hours', MEDIUM: '7 days', LOW: '30 days' };

return items.map(item => {
  const av      = item.json;
  const tier    = av.criticality_tier || 'LOW';
  const color   = colorMap[tier] || '#0088ff';
  const sla     = slaMap[tier]   || '30 days';
  const score   = av.risk_score         != null ? String(av.risk_score)         : 'N/A';
  const cvss    = av.cvss_v3_base_score != null ? String(av.cvss_v3_base_score) : 'N/A';
  const now     = new Date().toISOString().slice(0, 19).replace('T', ' ') + ' UTC';
  const cveId   = av.cve_id_str  || '';
  const asset   = av.asset_name  || 'Unknown';
  const team    = av.owner_team  || 'N/A';
  const pubDate = av.published_date ? String(av.published_date).slice(0, 10) : 'N/A';
  const rawDesc = av.cve_description || 'No description available.';
  const desc    = rawDesc.length > 280 ? rawDesc.slice(0, 277) + '...' : rawDesc;
  const nvdUrl  = 'https://nvd.nist.gov/vuln/detail/' + cveId;
  const subject = '[' + tier + '] ' + cveId + ' on ' + asset;

  // ── HTML email (color-coded per spec) ──────────────────────────────────────
  const css = 'body{font-family:Arial,sans-serif;margin:0;padding:0;background:#f4f4f4}'
    + '.wrap{max-width:600px;margin:20px auto;background:#fff;border-radius:6px;overflow:hidden;border:1px solid #ddd}'
    + '.top{background:' + color + ';padding:18px 24px;color:#fff;font-size:20px;font-weight:bold}'
    + '.body{padding:24px}table{width:100%;border-collapse:collapse}'
    + 'td{padding:8px 0;vertical-align:top;font-size:14px;color:#333;border-bottom:1px solid #f0f0f0}'
    + 'td:first-child{font-weight:bold;color:#666;width:140px;font-size:12px;text-transform:uppercase}'
    + '.btn{display:inline-block;margin-top:16px;padding:10px 20px;background:#0066cc;color:#fff;text-decoration:none;border-radius:4px;font-size:14px}'
    + '.foot{padding:12px 24px;background:#f9f9f9;font-size:11px;color:#aaa;border-top:1px solid #eee}';

  const emailHtml = '<!DOCTYPE html><html><head><meta charset="utf-8"><style>' + css + '</style></head>'
    + '<body><div class="wrap">'
    + '<div class="top">' + tier + ' Security Alert</div>'
    + '<div class="body"><table>'
    + '<tr><td>CVE ID</td><td>' + cveId + '</td></tr>'
    + '<tr><td>Risk Score</td><td><strong>' + score + ' / 10</strong></td></tr>'
    + '<tr><td>Affected Asset</td><td>' + asset + '</td></tr>'
    + '<tr><td>Owner Team</td><td>' + team + '</td></tr>'
    + '<tr><td>CVSS v3 Base</td><td>' + cvss + '</td></tr>'
    + '<tr><td>Published</td><td>' + pubDate + '</td></tr>'
    + '<tr><td>Description</td><td>' + desc + '</td></tr>'
    + '<tr><td>SLA</td><td>Remediate within <strong>' + sla + '</strong></td></tr>'
    + '</table>'
    + '<a href="' + nvdUrl + '" class="btn">View on NVD &rarr;</a>'
    + '</div>'
    + '<div class="foot">VulnPatchNotifier &middot; UTN FRM &middot; ' + now + '</div>'
    + '</div></body></html>';

  // ── Slack Block Kit payload ─────────────────────────────────────────────────
  const slackPayload = JSON.stringify({
    blocks: [
      {
        type: 'header',
        text: { type: 'plain_text', text: tier + ' Alert: ' + cveId, emoji: true }
      },
      {
        type: 'section',
        fields: [
          { type: 'mrkdwn', text: '*CVE:* ' + cveId },
          { type: 'mrkdwn', text: '*Risk Score:* ' + score + ' / 10' },
          { type: 'mrkdwn', text: '*Asset:* ' + asset },
          { type: 'mrkdwn', text: '*Owner:* ' + team }
        ]
      },
      {
        type: 'section',
        text: { type: 'mrkdwn', text: '*Description:* ' + desc }
      },
      {
        type: 'actions',
        elements: [
          {
            type: 'button',
            text: { type: 'plain_text', text: 'View on NVD', emoji: false },
            url: nvdUrl,
            style: 'primary'
          }
        ]
      },
      {
        type: 'context',
        elements: [
          { type: 'mrkdwn', text: 'SLA: *' + sla + '* | CVSS: ' + cvss + ' | VulnPatchNotifier' }
        ]
      }
    ]
  });

  return {
    json: {
      av_id:            av.av_id,
      cve_id_str:       cveId,
      risk_score:       av.risk_score,
      criticality_tier: tier,
      asset_name:       asset,
      owner_team:       team,
      recipient_email:  secEmail,
      subject,
      emailHtml,
      slackPayload,
      color
    }
  };
});

const emailInserts = $input.all();
const templates = $('Code Build Template').all();
return [{
  json: {
    recordsProcessed: templates.length,
    emailAlertsSent:  emailInserts.length
  }
}];
